python3 << 'EOF'
import fitz, numpy as np
doc = fitz.open('eprint/simple_limit.pdf')
p = doc[0]
d = p.get_drawings()[52]
pts = []
for it in d['items']:
    if it[0] == 'l':
        pts.append((it[1].x, it[1].y)); pts.append((it[2].x, it[2].y))
    elif it[0] == 'c':
        for pt in it[1:]:
            pts.append((pt.x, pt.y))
    elif it[0] == 're':
        print('rect item', it)
pts = np.array(pts)
print(len(pts), 'points')
print('x range', pts[:,0].min(), pts[:,0].max())
print('y range', pts[:,1].min(), pts[:,1].max())
# dedupe consecutive
def x2m(x): return 10**((x-451.7789611816406)/952.36)
def y2g(y): return 1e-11*10**((380.5140686035156-y)/364.047)
# print in order along path
seen=[]
for x,y in pts:
    if seen and abs(seen[-1][0]-x)<1e-6 and abs(seen[-1][1]-y)<1e-6: continue
    seen.append((x,y))
print('path pts:', len(seen))
for x,y in seen:
    print(f'{x:8.2f} {y:8.2f}   m={x2m(x):.4f} g={y2g(y):.4e}')
EOF
